import{z as B,x as p,o as E,c as d,q as o,j as t,D as e,d as r,s,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"HNSW / IVF","description":"","frontmatter":{"title":"HNSW / IVF","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hnsw-ivf.md","filePath":"llm/hnsw-ivf.md","lastUpdated":1791413859000}'),A={name:"llm/hnsw-ivf.md"};function h(F,a,c,m,f,S){const n=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="hnsw-ivf" tabindex="-1">HNSW / IVF <a class="header-anchor" href="#hnsw-ivf" aria-label="Permalink to &quot;HNSW / IVF&quot;">​</a></h1><div class="epigraph"><p>精确近邻随库规模线性扫。近似近邻用图或倒排粗量化换召回–延迟曲线。曲线是协议，不是「开了 HNSW 就无损」。</p><footer>—— Malkov &amp; Yashunin HNSW；Jégou 等 IVF 粗量化倒排</footer></div><p><a href="/llm/rag-context-compression">上一课</a>减少进入阅读器的 token。检索库本身仍可能是千万级向量。本课写 ANN 的两条默认结构：HNSW（图）与 IVF（倒排文件）。缺口是召回率对 \\(k\\)、efSearch、nprobe 的依赖。后课 PQ 在向量内部再压缩，常与 IVF 联用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 kNN 扫全库，延迟不可接受。HNSW 建多层可导航小世界图，搜索沿边贪心 + 候选集。IVF 先把空间分成粗心，查询只扫近的若干列表。二者都是近似：可能丢掉真正的邻居。RAG 里丢掉的若是唯一支撑块，忠实度直接掉。必须在<strong>自己的查询分布</strong>上画 Recall–延迟曲线，不能抄基准数字。</p><p>过滤（权限、租户）与图遍历交互：先过滤后搜或边搜边滤，实现错了会漏召回或漏出无权限文档。</p><p><span class="marginnote">「粗心」（centroid，粗量化中心）可以想象成把一座城市划成几个大区：查询先判断自己落在哪个区，只翻这个区的电话簿。nprobe 就是「除本区外再看几个邻区」——多看几个不容易漏人，但每多看一个就多扫一份列表，延迟线性涨。</span></p><p><span class="marginnote">建索引的超参（M、efConstruction、粗心个数）改的是图/列表质量，搜时的 efSearch / nprobe 改的是预算。两套都要进模型卡式的索引卡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选结构：内存允许、要高召回 → HNSW；库极大、可接受较低召回或配合 PQ → IVF。调参：固定延迟预算扫 efSearch 或 nprobe，看 Recall@\\(k\\)。\\(k\\) 应大于最终送给阅读器的块数，给融合与压缩留候选。增量插入：HNSW 可动态加边，IVF 列表 unbalanced 时要重建。</p>',10)),(E(),t(i,null,{default:e(()=>[s(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20QV%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20HNSW%5B%22HNSW%20%E5%9B%BE%E9%81%8D%E5%8E%86%22%5D%0A%20%20QV%20--%3E%20IVF%5B%22IVF%20%E9%80%89%E5%88%97%E8%A1%A8%E5%86%8D%E6%89%AB%22%5D%0A%20%20HNSW%20--%3E%20CAND%5B%22%E8%BF%91%E4%BC%BC%20Top-n%22%5D%0A%20%20IVF%20--%3E%20CAND%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"HNSW 的高层边是长距离高速公路，底层是精细邻居。efSearch 增大等于允许更宽的候选，逼近精确。IVF 的误差来自查询落在错误粗心附近——边界点会被切错列表，nprobe 增大即多探几个心。两者都把「真实近邻被剪掉」的概率换成延迟。这个概率在难查询（近邻很近、易混）上更高，平均召回会掩盖切片。",-1)),(E(),t(i,null,{default:e(()=>[s(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BB%8E%E9%A1%B6%E5%B1%82%E5%85%A5%E5%8F%A3%E5%87%BA%E5%8F%91%22%5D%20--%3E%20G1%5B%22%E9%A1%B6%E5%B1%82%EF%BC%9A%E7%A8%80%E7%96%8F%E9%95%BF%E8%BE%B9%EF%BC%8C%E5%BF%AB%E9%80%9F%E8%B7%B3%E8%BF%9C%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E9%80%90%E5%B1%82%E4%B8%8B%E9%99%8D%EF%BC%9A%E5%9B%BE%E5%8F%98%E5%AF%86%EF%BC%8C%E6%AD%A5%E8%B7%9D%E5%8F%98%E7%9F%AD%22%5D%0A%20%20G2%20--%3E%20G3%5B%22%E5%BA%95%E5%B1%82%EF%BC%9A%E7%B2%BE%E7%BB%86%E9%82%BB%E5%B1%85%EF%BC%8C%E8%B4%AA%E5%BF%83%E9%80%BC%E8%BF%91%E7%9B%AE%E6%A0%87%22%5D%0A%20%20G3%20--%3E%20E%5B%22%E5%80%99%E9%80%89%E9%9B%86%E5%AE%BD%E5%BA%A6%E7%94%B1%20efSearch%20%E6%8E%A7%E5%88%B6%22%5D%0A%20%20E%20--%3E%20R%5B%22%E8%BF%94%E5%9B%9E%E8%BF%91%E4%BC%BC%20Top-k%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：一千万条向量的库，efSearch=64 时每次查询只实际碰几千条，比全库扫描少约三个数量级；代价是 Recall@10 可能只有 0.95 而不是 1.0。把 efSearch 拉大一倍召回往往只涨一两个点，延迟却近乎翻倍——你的 SLA 定在哪一格，要在自己的查询分布上量出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ANN 不修复坏嵌入。空间本身塌了，图再好也搜不到。下一课 PQ：把向量量化进码本，内存再降一截，误差再加一层。</p><p><span class="marginnote">初学者容易以为权限过滤就是「先搜出 Top-10，再删掉没权限的」。若某租户被过滤掉 8 条，最终只剩 2 条可用，回答质量已经受损；正确做法是把过滤条件带进遍历（边搜边滤）或扩大候选 k，保证过滤后的数量仍然够用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HNSW / IVF 用近似换延迟，必须报自己分布上的 Recall–延迟。</li><li>搜时预算与建时超参都要版本化。</li><li>权限过滤与遍历实现属于正确性，不只是性能。</li><li>出处：Malkov &amp; Yashunin HNSW；Jégou 等 IVF。</li></ul>',6))])}const V=B(A,[["render",h]]);export{u as __pageData,V as default};
